-- 船舶类型字典表
CREATE TABLE vessel_type_dict (
    type_code SMALLINT PRIMARY KEY COMMENT 'AIS船舶类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称',
    category VARCHAR(20) COMMENT '大类'
) ENGINE=InnoDB COMMENT='船舶类型字典';

-- 人员类型字典表
CREATE TABLE employee_type_dict (
    type_code VARCHAR(20) PRIMARY KEY COMMENT '人员类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称（船长/大副/轮机长/水手等）'
) ENGINE=InnoDB COMMENT='人员类型字典';

-- 企业规模划型字典表
CREATE TABLE dict_size_category (
    size_code VARCHAR(10) PRIMARY KEY COMMENT '规模代码',
    size_name VARCHAR(20) NOT NULL COMMENT '规模名称'
) COMMENT='企业规模划型字典';

